// ===========================================

let currentProjectId = null;
let currentProject = null;
let currentClient = null;
let units = [];
let works = [];
let employees = [];
let currentMaterialsFilter = 'all'; // Текущий фильтр СНАБ
let allMaterialsEstimate = []; // Все материалы для фильтрации
let allMaterialsExpenses = []; // Все расходы для фильтрации
let materialsDropdownTimeout; // Таймаут для фильтрации выпадающего списка материалов
let resourceCategories = []; // Категории ресурсов работ
let expandedWorks = new Set(); // Множество ID раскрытых работ
let currentWorksFilter = 'all'; // Текущий фильтр работ

// Загрузка данных при загрузке страницы
document.addEventListener('DOMContentLoaded', async () => {
    // Получаем ID проекта из URL
    const urlParams = new URLSearchParams(window.location.search);
    currentProjectId = urlParams.get('id');
    
    if (!currentProjectId) {
        alert('Не указан ID проекта');
        window.location.href = 'taiga.html';
        return;
    }
    
    await loadUnits();
    await loadEmployees();
    await loadResourceCategories();
    await loadExpenseCategories();
    await loadProject();
    await loadAllTabs();
});

// Загрузка единиц измерения
async function loadUnits() {
    try {
        units = await api.get('/units');
    } catch (error) {
        console.error('Ошибка загрузки единиц измерения:', error);
    }
}

// Загрузка сотрудников
async function loadEmployees() {
    try {
        // Загружаем всех сотрудников (без фильтра по статусу)
        employees = await employeesAPI.getAll();
    } catch (error) {
        console.error('Ошибка загрузки сотрудников:', error);
    }
}

// Загрузка информации о проекте
async function loadProject() {
    try {
        currentProject = await projectsAPI.getById(currentProjectId);
        const clients = await clientsAPI.getAll();
        currentClient = clients.find(c => c.id === currentProject.client_id);
        
        // Обновляем заголовок "Опись работ"
        updateWorksHeader();
    } catch (error) {
        console.error('Ошибка загрузки проекта:', error);
    }
}

// Обновление заголовка "Опись работ"
function updateWorksHeader() {
    // Убираем старый заголовок - больше не нужен
    // Добавляем имя клиента в заголовок таблицы
    const clientNameSpan = document.getElementById('client-name-in-header');
    if (clientNameSpan && currentClient) {
        clientNameSpan.textContent = currentClient.name;
    }
}

// Загрузка всех вкладок
async function loadAllTabs() {
    await loadStatistics();
    await loadWorks();
    await loadMaterials();
    await loadJournal();
    await loadTimesheet();
}

// ===========================================
// ВКЛАДКА: СТАТИСТИКА
// ===========================================

async function loadStatistics() {
    try {
        const stats = await projectStatisticsAPI.getByProject(currentProjectId);
        renderStatistics(stats);
    } catch (error) {
        console.error('Ошибка загрузки статистики:', error);
        document.getElementById('stat-tbody').innerHTML = 
            '<tr><td colspan="5" class="empty-state">Ошибка загрузки данных</td></tr>';
    }
}

function renderStatistics(stats) {
    const tbody = document.getElementById('stat-tbody');
    
    if (stats.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" class="empty-state"><p>Нет данных</p></td></tr>';
        return;
    }
    
    // Сортируем по дате (новые сверху)
    const sorted = [...stats].sort((a, b) => new Date(b.date) - new Date(a.date));
    
    tbody.innerHTML = sorted.map(stat => {
        const diff = (parseFloat(stat.actual_percent) || 0) - (parseFloat(stat.planned_percent) || 0);
        const diffClass = diff >= 0 ? 'positive' : 'negative';
        const diffSign = diff >= 0 ? '+' : '';
        
        return `
            <tr>
                <td>${formatDate(stat.date)}</td>
                <td>${formatNumber(stat.planned_percent)}%</td>
                <td>${formatNumber(stat.actual_percent)}%</td>
                <td class="${diffClass}">${diffSign}${formatNumber(diff)}%</td>
                <td>
                    <button class="btn btn-danger" onclick="deleteStat(${stat.id})">Удалить</button>
                </td>
            </tr>
        `;
    }).join('');
}

// ===========================================
// ВКЛАДКА: РАБОТЫ
// ===========================================

async function loadWorks() {
    try {
        works = await projectWorksAPI.getByProject(currentProjectId);
        console.log('Загружено работ:', works.length);
        if (works.length > 0) {
            console.log('Первая работа:', JSON.stringify(works[0], null, 2));
            console.log('work_name:', works[0].work_name);
            console.log('section_name:', works[0].section_name);
            console.log('work_type_name:', works[0].work_type_name);
        }
        renderWorks(works);
        
        // Обновляем заголовок на случай, если данные проекта загрузились позже
        updateWorksHeader();
    } catch (error) {
        console.error('Ошибка загрузки работ:', error);
        document.getElementById('works-tbody').innerHTML = 
            '<tr><td colspan="5" class="empty-state">Ошибка загрузки данных: ' + error.message + '</td></tr>';
    }
}

function renderWorks(worksList) {
    // Применяем фильтр перед отображением
    const filtered = applyWorksFilter(worksList);
    const tbody = document.getElementById('works-tbody');
    
    if (!filtered || filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="empty-state"><p>Нет работ</p></td></tr>';
        return;
    }
    
    console.log('Отладочная информация о работах:', filtered.slice(0, 3));
    console.log('Ключи первой работы:', Object.keys(filtered[0]));
    
    // Группируем по разделам
    const grouped = {};
    filtered.forEach(work => {
        // Используем section_name из нового представления
        const section = work.section_name || work.section_alias || work.section || 'Общие';
        if (!grouped[section]) {
            grouped[section] = [];
        }
        grouped[section].push(work);
    });
    
    let html = '';
    // Сортируем разделы по минимальному sort_order в разделе
    const sortedSections = Object.keys(grouped).sort((a, b) => {
        const minOrderA = Math.min(...grouped[a].map(w => parseFloat(w.sort_order) || 9999));
        const minOrderB = Math.min(...grouped[b].map(w => parseFloat(w.sort_order) || 9999));
        return minOrderA - minOrderB;
    });
    
    sortedSections.forEach(section => {
        html += `<tr class="section-header"><td colspan="8"><strong>${section}</strong></td></tr>`;
        // Сортируем работы внутри раздела по sort_order
        const sortedWorks = grouped[section].sort((a, b) => {
            const orderA = parseFloat(a.sort_order) || 9999;
            const orderB = parseFloat(b.sort_order) || 9999;
            return orderA - orderB;
        });
        sortedWorks.forEach(work => {
            // Используем данные из представления
            const unitName = work.unit_short_name || work.unit_name || '-';
            let progress = parseFloat(work.progress_percent) || 0;
            // Ограничиваем прогресс максимумом 100% для корректного отображения
            progress = Math.min(progress, 100);
            // Выделяем слабокрасным, если quantity = 0
            const rowClass = (parseFloat(work.quantity) || 0) === 0 ? 'quantity-zero' : '';
            
            // Формируем название работы: сначала из представления, потом вручную
            let workName = work.work_name;
            if (!workName || workName === 'null' || workName === null) {
                if (work.section_name && work.work_type_name) {
                    workName = work.section_name + ' - ' + work.work_type_name;
                } else if (work.work_type_name) {
                    workName = work.work_type_name;
                } else {
                    workName = 'Нет названия';
                }
            }
            
            // Убираем категории из наименования (например, "Вентиляция - Приточные клапаны" → "Приточные клапаны")
            // Если есть " - ", берём только часть после последнего " - "
            if (workName && workName.includes(' - ')) {
                const parts = workName.split(' - ');
                // Если частей больше 1, берём последнюю часть
                if (parts.length > 1) {
                    workName = parts[parts.length - 1].trim();
                }
            }
            
            // Создаём стиль для прогресс-бара в строке
            const progressStyle = `background: linear-gradient(to right, #d4edda ${progress}%, transparent ${progress}%);`;
            
            const isExpanded = expandedWorks.has(work.id);
            const arrow = isExpanded ? '▲' : '▼';
            
            html += `
                <tr class="${rowClass} work-progress-row ${isExpanded ? 'work-row-expanded' : ''}" 
                    style="${progressStyle}" 
                    data-work-id="${work.id}">
                    <td>
                        <span style="cursor: pointer; font-size: 14px; color: var(--secondary-color); user-select: none;" 
                              onclick="toggleWorkResources(${work.id})" 
                              title="Показать/скрыть ресурсы">
                            ${arrow}
                        </span>
                    </td>
                    <td>${work.section_alias || work.section_name || ''}</td>
                    <td>${workName}</td>
                    <td>${unitName}</td>
                    <td style="text-align: right;">${formatNumber(work.quantity)}</td>
                    <td style="text-align: right;">${formatNumber(work.completed_quantity || 0)}</td>
                    <td style="text-align: right;">${formatNumber((parseFloat(work.quantity) || 0) - (parseFloat(work.completed_quantity) || 0))}</td>
                    <td class="actions-cell">
                        <button 
                            onclick="openEditWorkModal(${work.id})"
                            title="Редактировать работу"
                            class="action-btn edit-btn"
                        >✏️</button>
                    </td>
                </tr>
                <tr class="work-resources-row" data-work-id="${work.id}" style="display: ${isExpanded ? 'table-row' : 'none'};">
                    <td colspan="8" style="padding: 0;">
                        <div class="work-resources-accordion ${isExpanded ? 'active' : ''}" id="resources-${work.id}">
                            <div class="work-resources-header">
                                <h4>Ресурсы для работы</h4>
                                <button class="btn btn-primary" onclick="event.stopPropagation(); openAddResourceModal(${work.id})" style="padding: 5px 10px; font-size: 12px;">+ Добавить ресурс</button>
                            </div>
                            <div class="work-resources-list" id="resources-list-${work.id}">
                                <div class="loading">Загрузка ресурсов...</div>
                            </div>
                        </div>
                    </td>
                </tr>
            `;
        });
    });
    
    tbody.innerHTML = html;
}

// Фильтрация работ
function filterWorks(filter) {
    currentWorksFilter = filter;
    
    // Обновляем активный класс у фильтров
    document.querySelectorAll('.works-filters .filter-link').forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('data-filter') === filter) {
            link.classList.add('active');
        }
    });
    
    // Применяем фильтр и перерисовываем
    const filtered = applyWorksFilter(works);
    renderWorks(filtered);
}

function applyWorksFilter(worksList) {
    if (!worksList || worksList.length === 0) {
        return [];
    }
    
    if (currentWorksFilter === 'all') {
        return worksList;
    }
    
    return worksList.filter(work => {
        const progress = parseFloat(work.progress_percent) || 0;
        const completed = parseFloat(work.completed_quantity) || 0;
        const quantity = parseFloat(work.quantity) || 0;
        const remaining = quantity - completed;
        
        switch (currentWorksFilter) {
            case 'in-progress':
                // В процессе: прогресс > 0 и < 100
                return progress > 0 && progress < 100;
            case 'done':
                // Готов: прогресс >= 100
                return progress >= 100;
            case 'remaining':
                // Остались: есть что делать (completed < quantity)
                return remaining > 0;
            default:
                return true;
        }
    });
}

// ===========================================
// ВКЛАДКА: СНАБ (МАТЕРИАЛЫ)
// ===========================================

async function loadMaterials() {
    try {
        // Загружаем смету материалов
        allMaterialsEstimate = await projectMaterialsAPI.getByProject(currentProjectId);
        
        // Загружаем фактические расходы
        allMaterialsExpenses = await expensesAPI.getByProject(currentProjectId);
        
        // Синхронизируем ресурсы работ с СНАБ
        await syncAllWorkResourcesToMaterials();
        
        // Перезагружаем материалы после синхронизации
        allMaterialsEstimate = await projectMaterialsAPI.getByProject(currentProjectId);
        
        // Применяем фильтр
        const filtered = applyMaterialsFilter(allMaterialsEstimate, allMaterialsExpenses);
        renderMaterials(filtered.estimate, filtered.expenses);
        updateMaterialsSummary(filtered.estimate, filtered.expenses);
    } catch (error) {
        console.error('Ошибка загрузки материалов:', error);
        document.getElementById('materials-tbody').innerHTML = 
            '<tr><td colspan="11" class="empty-state">Ошибка загрузки данных</td></tr>';
    }
}

// Синхронизация всех ресурсов работ с материалами в СНАБ
async function syncAllWorkResourcesToMaterials() {
    try {
        // Загружаем все ресурсы всех работ
        const allResources = {};
        for (const work of works) {
            const resources = await workResourcesAPI.getByWork(work.id);
            resources.forEach(resource => {
                const key = `${resource.material_name}_${resource.resource_category_id}_${resource.unit_id}`;
                if (!allResources[key]) {
                    allResources[key] = {
                        ...resource,
                        totalQuantity: 0,
                        workIds: []
                    };
                }
                // Суммируем количество только если ресурс не общий
                if (!resource.is_shared) {
                    allResources[key].totalQuantity += parseFloat(resource.quantity) || 0;
                } else {
                    // Для общих ресурсов берём максимальное количество (или 1)
                    allResources[key].totalQuantity = Math.max(
                        allResources[key].totalQuantity,
                        parseFloat(resource.quantity) || 1
                    );
                }
                allResources[key].workIds.push(work.id);
            });
        }
        
        // Синхронизируем каждый ресурс с СНАБ
        for (const key in allResources) {
            const resource = allResources[key];
            const materials = await projectMaterialsAPI.getByProject(currentProjectId);
            const existingMaterial = materials.find(m => 
                m.material_name === resource.material_name && 
                m.resource_category_id === resource.resource_category_id &&
                m.unit_id === resource.unit_id
            );
            
            if (existingMaterial) {
                // Обновляем количество, если изменилось
                const newQuantity = resource.is_shared ? 1 : resource.totalQuantity;
                if (Math.abs(parseFloat(existingMaterial.planned_quantity || 0) - newQuantity) > 0.01) {
                    await projectMaterialsAPI.update(existingMaterial.id, {
                        planned_quantity: newQuantity,
                        planned_cost: newQuantity * (parseFloat(existingMaterial.planned_price) || 0)
                    });
                }
            } else {
                // Создаём новый материал
                const categoryName = resourceCategories.find(c => c.id === resource.resource_category_id)?.name || '';
                await projectMaterialsAPI.create({
                    project_id: currentProjectId,
                    category: categoryName,
                    material_name: resource.material_name,
                    unit_id: resource.unit_id,
                    planned_quantity: resource.is_shared ? 1 : resource.totalQuantity,
                    planned_price: 0,
                    planned_cost: 0,
                    resource_category_id: resource.resource_category_id
                });
            }
        }
    } catch (error) {
        console.error('Ошибка синхронизации ресурсов с СНАБ:', error);
    }
}

// Применение фильтра к материалам
function applyMaterialsFilter(estimate, expenses) {
    let filteredEstimate = [...estimate];
    let filteredExpenses = [...expenses];
    
    // Фильтр по статусу покупки
    if (currentMaterialsFilter === 'purchased') {
        // Только купленные (есть фактические расходы)
        const purchasedNames = new Set(expenses.map(e => e.subcategory).filter(Boolean));
        filteredEstimate = filteredEstimate.filter(m => purchasedNames.has(m.material_name));
    } else if (currentMaterialsFilter === 'remaining') {
        // Только не купленные (нет фактических расходов или количество меньше планового)
        const expensesByMaterial = {};
        expenses.forEach(exp => {
            const key = exp.subcategory || '';
            if (!expensesByMaterial[key]) {
                expensesByMaterial[key] = [];
            }
            expensesByMaterial[key].push(exp);
        });
        filteredEstimate = filteredEstimate.filter(m => {
            const factExpenses = expensesByMaterial[m.material_name] || [];
            const factQuantity = factExpenses.reduce((sum, e) => sum + (parseFloat(e.quantity) || 0), 0);
            const plannedQty = parseFloat(m.planned_quantity) || 0;
            return factQuantity < plannedQty;
        });
    }
    
    // Фильтр по категории ресурса
    const categoryMap = {
        'material': 'Материал',
        'consumable': 'Расходник',
        'tool': 'Инструмент',
        'overhead': 'Накладные'
    };
    
    if (categoryMap[currentMaterialsFilter]) {
        const categoryName = categoryMap[currentMaterialsFilter];
        filteredEstimate = filteredEstimate.filter(m => {
            // Находим категорию ресурса по resource_category_id
            if (m.resource_category_id) {
                const category = resourceCategories.find(c => c.id === m.resource_category_id);
                return category && category.name === categoryName;
            }
            // Если категория не указана, проверяем по category (старое поле)
            return m.category === categoryName;
        });
    }
    
    return { estimate: filteredEstimate, expenses: filteredExpenses };
}

// Функция фильтрации материалов
function filterMaterials(filter) {
    currentMaterialsFilter = filter;
    
    // Обновляем активные ссылки
    document.querySelectorAll('.filter-link').forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('data-filter') === filter) {
            link.classList.add('active');
        }
    });
    
    // Применяем фильтр
    const filtered = applyMaterialsFilter(allMaterialsEstimate, allMaterialsExpenses);
    renderMaterials(filtered.estimate, filtered.expenses);
    updateMaterialsSummary(filtered.estimate, filtered.expenses);
}

function renderMaterials(estimate, expenses) {
    const tbody = document.getElementById('materials-tbody');
    
    if (estimate.length === 0) {
        tbody.innerHTML = '<tr><td colspan="12" class="empty-state"><p>Нет материалов в смете</p></td></tr>';
        return;
    }
    
    // Группируем расходы по названию материала
    const expensesByMaterial = {};
    expenses.forEach(exp => {
        const key = exp.subcategory || '';
        if (!expensesByMaterial[key]) {
            expensesByMaterial[key] = [];
        }
        expensesByMaterial[key].push(exp);
    });
    
    // Группируем по категориям
    const grouped = {};
    estimate.forEach(mat => {
        const category = mat.category || 'Общие';
        if (!grouped[category]) {
            grouped[category] = [];
        }
        grouped[category].push(mat);
    });
    
    let html = '';
    Object.keys(grouped).forEach(category => {
        html += `<tr class="section-header"><td colspan="12"><strong>${category}</strong></td></tr>`;
        grouped[category].forEach(mat => {
            const unit = mat.unit_id ? units.find(u => u.id === mat.unit_id) : null;
            const unitName = unit ? (unit.short_name || unit.name) : '-';
            
            // Находим фактические данные
            const factExpenses = expensesByMaterial[mat.material_name] || [];
            const factQuantity = factExpenses.reduce((sum, e) => sum + (parseFloat(e.quantity) || 0), 0);
            const factAmount = factExpenses.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);
            const factPrice = factQuantity > 0 ? factAmount / factQuantity : 0;
            
            // Разница в количестве (докупить)
            const plannedQty = parseFloat(mat.planned_quantity) || 0;
            const remainingQty = plannedQty - factQuantity;
            const remainingQtyClass = remainingQty > 0 ? 'positive' : (remainingQty < 0 ? 'negative' : '');
            
            // Стоимость дозакупа = ещё.кол-во * смета.цена
            const plannedPrice = parseFloat(mat.planned_price) || 0;
            const remainingCost = remainingQty > 0 ? remainingQty * plannedPrice : 0;
            const remainingCostClass = remainingQty > 0 ? 'positive' : (remainingQty < 0 ? 'negative' : '');
            
            // Выгода рассчитывается только если количество сметы и факта совпадают (докупить = 0)
            const canCalculateSavings = Math.abs(remainingQty) < 0.01; // Учитываем погрешность округления
            let savings = 0;
            let savingsClass = '';
            
            html += `<tr>
                <td>${mat.material_name || '-'}</td>
                <td>${unitName}</td>
                <td>${formatNumber(plannedQty)}</td>
                <td>${formatNumber(plannedPrice)}</td>
                <td>${formatNumber(mat.planned_cost || 0)}</td>
                <td>${formatNumber(factQuantity)}</td>
                <td>${formatNumber(factPrice)}</td>
                <td>${formatNumber(factAmount)}</td>
                <td class="${remainingQtyClass}">${formatNumber(remainingQty)}</td>
                <td class="${remainingCostClass}">${formatNumber(remainingCost)}</td>
                <td class="${savingsClass}">${formatNumber(savings)}</td>
                <td>-</td>
            </tr>`;
        });
    });
    
    tbody.innerHTML = html;
}

function updateMaterialsSummary(estimate, expenses) {
    const totalMaterials = estimate.length;
    const plannedCost = estimate.reduce((sum, m) => sum + (parseFloat(m.planned_cost) || 0), 0);
    
    const factExpenses = expenses.filter(e => e.category_id && 
        (e.category_id === estimate.find(m => m.category === 'Мат')?.category_id || 
         e.subcategory && estimate.some(m => m.material_name === e.subcategory)));
    
    const purchasedCount = new Set(factExpenses.map(e => e.subcategory)).size;
    const factAmount = factExpenses.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);
    
    const supplyPercent = totalMaterials > 0 ? (purchasedCount / totalMaterials * 100) : 0;
    const savings = plannedCost - factAmount;
    const remaining = plannedCost - factAmount;
    
    document.getElementById('total-materials').textContent = totalMaterials;
    document.getElementById('planned-cost').textContent = formatNumber(plannedCost);
    document.getElementById('purchased-count').textContent = purchasedCount;
    document.getElementById('supply-percent').textContent = formatNumber(supplyPercent) + '%';
    document.getElementById('savings').textContent = formatNumber(savings);
    document.getElementById('remaining').textContent = formatNumber(remaining);
}

// ===========================================
// ВКЛАДКА: ЖУРНАЛ
// ===========================================

async function loadJournal() {
    try {
        const journal = await projectJournalAPI.getByProject(currentProjectId);
        renderJournal(journal);
    } catch (error) {
        console.error('Ошибка загрузки журнала:', error);
        document.getElementById('journal-tbody').innerHTML = 
            '<tr><td colspan="9" class="empty-state">Ошибка загрузки данных</td></tr>';
    }
}

function renderJournal(journal) {
    const tbody = document.getElementById('journal-tbody');
    
    if (journal.length === 0) {
        tbody.innerHTML = '<tr><td colspan="9" class="empty-state"><p>Нет записей</p></td></tr>';
        return;
    }
    
    // Сортируем по дате и времени (новые сверху)
    const sorted = [...journal].sort((a, b) => {
        const dateA = new Date(a.date);
        const dateB = new Date(b.date);
        if (dateB - dateA !== 0) return dateB - dateA;
        // Если даты равны, сортируем по времени начала
        if (a.time_start && b.time_start) {
            return b.time_start.localeCompare(a.time_start);
        }
        return 0;
    });
    
    tbody.innerHTML = sorted.map(entry => {
        const work = entry.work_id ? works.find(w => w.id === entry.work_id) : null;
        const workName = work ? work.work_name : '-';
        const unit = work && work.unit_id ? units.find(u => u.id === work.unit_id) : null;
        const unitName = unit ? (unit.short_name || unit.name) : '';
        
        // Форматируем время
        const timeStr = entry.time_start && entry.time_end 
            ? `${entry.time_start.substring(0, 5)} - ${entry.time_end.substring(0, 5)}`
            : '-';
        
        // Форматируем часы (без десятичных)
        const hoursStr = entry.hours ? Math.round(parseFloat(entry.hours)).toString() : '-';
        
        // Форматируем сотрудников
        let employeesList = '-';
        // Проверяем, что employees существует
        if (entry.employees !== null && entry.employees !== undefined) {
            // Если это строка, пытаемся распарсить
            let employeesArray = entry.employees;
            if (typeof entry.employees === 'string') {
                try {
                    employeesArray = JSON.parse(entry.employees);
                } catch (e) {
                    console.warn('Ошибка парсинга employees:', e);
                    employeesArray = [];
                }
            }
            // Если это массив и не пустой
            if (Array.isArray(employeesArray) && employeesArray.length > 0) {
                employeesList = employeesArray.map(e => {
                    if (!e) return '';
                    // Используем full_name если есть
                    if (e.full_name && e.full_name.trim()) {
                        return e.full_name.trim();
                    }
                    // Иначе собираем из частей
                    const parts = [e.last_name, e.first_name, e.middle_name].filter(x => x && x.trim());
                    return parts.length > 0 ? parts.join(' ').trim() : 'Без имени';
                }).filter(x => x).join(', ');
            }
        }
        
        // Если есть примечания с подрядчиком, добавляем в сотрудники
        if (entry.notes && entry.notes.includes('Подрядчик')) {
            const contractorName = entry.notes.replace('Подрядчик', '').trim();
            if (employeesList === '-') {
                employeesList = contractorName;
            } else {
                employeesList += ', ' + contractorName;
            }
        }
        
        // Выполнено (только число)
        const completedStr = entry.quantity_completed ? formatNumber(entry.quantity_completed) : '-';
        
        // Единица измерения
        const unitDisplay = unitName || '-';
        
        // Используем историческое значение "Осталось" из записи журнала
        // Если его нет (старые записи), вычисляем как fallback
        let remaining = '-';
        if (entry.remaining_at_time !== null && entry.remaining_at_time !== undefined) {
            // Используем сохраненное историческое значение
            remaining = formatNumber(parseFloat(entry.remaining_at_time) || 0);
        } else if (work && work.quantity !== null && work.quantity !== undefined) {
            // Fallback для старых записей: вычисляем текущее значение
            const total = parseFloat(work.quantity) || 0;
            const workCompleted = parseFloat(work.completed_quantity) || 0;
            const remainingTotal = total - workCompleted;
            remaining = formatNumber(remainingTotal);
        }
        
        return `
            <tr>
                <td>${formatDate(entry.date)}</td>
                <td>${timeStr}</td>
                <td>${hoursStr}</td>
                <td>${employeesList}</td>
                <td>${workName}</td>
                <td>${completedStr}</td>
                <td>${unitDisplay}</td>
                <td>${remaining}</td>
                <td class="actions-cell">
                    <button 
                        onclick="openEditJournalModal(${entry.id})"
                        title="Редактировать"
                        class="action-btn edit-btn"
                    >✏️</button>
                    <button 
                        onclick="deleteJournalEntry(${entry.id})"
                        title="Удалить"
                        class="action-btn delete-btn"
                    >✕</button>
                </td>
            </tr>
        `;
    }).join('');
}

