// Фильтрация выпадающего списка материалов
function filterMaterialsDropdown() {
    clearTimeout(materialsDropdownTimeout);
    const searchInput = document.getElementById('material-name-search');
    if (!searchInput) return;
    
    const search = searchInput.value.trim(); // Убираем toLowerCase(), чтобы сохранить кириллицу
    const dropdown = document.getElementById('materials-dropdown');
    
    if (!dropdown) return;
    
    if (!search) {
        dropdown.innerHTML = '';
        dropdown.style.display = 'none';
        return;
    }
    
    materialsDropdownTimeout = setTimeout(async () => {
        try {
            const filtered = await loadMaterialsList(search);
            if (filtered.length === 0) {
                dropdown.innerHTML = '<div class="dropdown-item">Материал не найден</div>';
            } else {
                dropdown.innerHTML = filtered.slice(0, 10).map(mat => `
                    <div class="dropdown-item" onclick="selectMaterial(${mat.id}, '${mat.mat.replace(/'/g, "\\'").replace(/"/g, '&quot;')}', ${mat.primary_unit || 'null'}, ${mat.cat_expense_id || 'null'})">
                        ${mat.category_icon || ''} ${mat.mat} 
                        <span style="color: #999; font-size: 12px;">(${mat.primary_unit_name || ''})</span>
                    </div>
                `).join('');
            }
            dropdown.style.display = 'block';
        } catch (error) {
            console.error('Ошибка поиска материалов:', error);
            dropdown.innerHTML = '<div class="dropdown-item" style="color: red;">Ошибка поиска</div>';
            dropdown.style.display = 'block';
        }
    }, 300);
}

// Показать выпадающий список
async function showMaterialsDropdown() {
    const searchInput = document.getElementById('material-name-search');
    if (!searchInput) return;
    
    const search = searchInput.value.trim();
    const dropdown = document.getElementById('materials-dropdown');
    if (!dropdown) return;
    
    if (search) {
        filterMaterialsDropdown();
    } else {
        // Показываем первые 10 материалов
        if (materialsList.length === 0) {
            await loadMaterialsList();
        }
        dropdown.innerHTML = materialsList.slice(0, 10).map(mat => `
            <div class="dropdown-item" onclick="selectMaterial(${mat.id}, '${mat.mat.replace(/'/g, "\\'").replace(/"/g, '&quot;')}', ${mat.primary_unit || 'null'}, ${mat.cat_expense_id || 'null'})">
                ${mat.category_icon || ''} ${mat.mat} 
                <span style="color: #999; font-size: 12px;">(${mat.primary_unit_name || ''})</span>
            </div>
        `).join('');
        dropdown.style.display = 'block';
    }
}

// Выбор материала из списка
function selectMaterial(materialId, materialName, unitId, categoryId) {
    document.getElementById('material-name-search').value = materialName;
    document.getElementById('add-material-form').setAttribute('data-material-id', materialId);
    
    if (unitId) {
        document.getElementById('material-unit').value = unitId;
    }
    
    if (categoryId) {
        document.getElementById('material-category').value = categoryId;
    }
    
    document.getElementById('materials-dropdown').style.display = 'none';
}

// Переключение формы добавления нового материала
function toggleAddNewMaterial() {
    const form = document.getElementById('new-material-form');
    form.style.display = form.style.display === 'none' ? 'block' : 'none';
}

// Добавление нового материала в _list_mat "на лету"
async function addNewMaterialToList() {
    const name = document.getElementById('new-material-name').value.trim();
    const unitId = document.getElementById('new-material-unit').value;
    const categoryId = document.getElementById('material-category').value;
    
    if (!name || !unitId || !categoryId) {
        alert('Заполните все поля: название, единица измерения и категория');
        return;
    }
    
    try {
        const newMaterial = await listMatAPI.create({
            mat: name,
            cat_expense_id: parseInt(categoryId),
            primary_unit: parseInt(unitId)
        });
        
        // Обновляем список материалов
        await loadMaterialsList();
        
        // Выбираем новый материал
        selectMaterial(newMaterial.id, newMaterial.mat, newMaterial.primary_unit, newMaterial.cat_expense_id);
        
        // Скрываем форму добавления
        document.getElementById('new-material-form').style.display = 'none';
        document.getElementById('new-material-name').value = '';
        document.getElementById('new-material-unit').value = '';
        
        alert('✅ Материал добавлен в справочник!');
    } catch (error) {
        console.error('Ошибка добавления материала:', error);
        alert('Ошибка добавления материала: ' + error.message);
    }
}

// Расчёт стоимости материала
function calculateMaterialCost() {
    const quantity = parseFloat(document.getElementById('material-quantity').value) || 0;
    const price = parseFloat(document.getElementById('material-price').value) || 0;
    const cost = quantity * price;
    document.getElementById('material-cost').value = cost.toFixed(2);
}

