// Загрузка категорий расходов
async function loadExpenseCategories() {
    try {
        if (expenseCategories.length === 0) {
            expenseCategories = await api.get('/expense-categories');
        }
    } catch (error) {
        console.error('Ошибка загрузки категорий расходов:', error);
    }
}

// Загрузка списка материалов из _list_mat
async function loadMaterialsList(search = '') {
    try {
        const params = {};
        if (search && search.trim()) {
            params.search = search.trim(); // Убираем пробелы, но сохраняем регистр для кириллицы
        }
        const result = await listMatAPI.getAll(params);
        // Если это поиск, возвращаем только результаты поиска
        // Если это общая загрузка, сохраняем в materialsList
        if (!search || !search.trim()) {
            materialsList = result;
        }
        return result;
    } catch (error) {
        console.error('Ошибка загрузки списка материалов:', error);
        return [];
    }
}

// Открытие модального окна для добавления материала
async function openAddMaterialModal(materialId = null) {
    if (expenseCategories.length === 0) {
        await loadExpenseCategories();
    }
    
    // Загружаем список материалов
    await loadMaterialsList();
    
    // Создаём модальное окно
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.id = 'add-material-modal';
    modal.style.display = 'block';
    
    // Определяем, редактируем ли мы существующий материал
    const isEdit = materialId !== null;
    let existingMaterial = null;
    let materialFromList = null;
    
    if (isEdit) {
        try {
            existingMaterial = await projectMaterialsAPI.getById(materialId);
            
            // Если есть material_id, загружаем данные из _list_mat
            if (existingMaterial && existingMaterial.material_id) {
                try {
                    materialFromList = await listMatAPI.getById(existingMaterial.material_id);
                } catch (error) {
                    console.warn('Не удалось загрузить материал из _list_mat по ID:', error);
                }
            }
            
            // Если material_id нет, но есть material_name, пытаемся найти в _list_mat по имени
            if (!materialFromList && existingMaterial && existingMaterial.material_name) {
                try {
                    const searchResults = await listMatAPI.getAll({ search: existingMaterial.material_name });
                    // Ищем точное совпадение
                    materialFromList = searchResults.find(m => m.mat === existingMaterial.material_name);
                } catch (error) {
                    console.warn('Не удалось найти материал в _list_mat по имени:', error);
                }
            }
        } catch (error) {
            console.error('Ошибка загрузки материала:', error);
            alert('Ошибка загрузки материала для редактирования: ' + error.message);
            return;
        }
    }
    
    modal.innerHTML = `
        <div class="modal-content resource-modal" style="max-width: 600px;">
            <div class="modal-header">
                <h3>${isEdit ? '✏️ Редактировать материал' : '➕ Добавить материал'}</h3>
                <button class="modal-close" onclick="closeAddMaterialModal()">×</button>
            </div>
            <div class="modal-body">
                <form id="add-material-form" onsubmit="event.preventDefault(); saveMaterial(${materialId || 'null'})">
                    <div class="form-group">
                        <label>📦 Категория <span class="required">*</span></label>
                        <select id="material-category" required>
                            <option value="">Выберите категорию</option>
                            ${expenseCategories.map(cat => 
                                `<option value="${cat.id}" ${existingMaterial && existingMaterial.resource_category_id === cat.id ? 'selected' : ''}>
                                    ${cat.icon || ''} ${cat.name}
                                </option>`
                            ).join('')}
                        </select>
                    </div>
                    <div class="form-group">
                        <label>📝 Наименование <span class="required">*</span></label>
                        <div style="position: relative;">
                            <input 
                                type="text" 
                                id="material-name-search" 
                                autocomplete="off"
                                placeholder="Начните вводить название или выберите из списка"
                                value="${existingMaterial ? (existingMaterial.material_name || '') : ''}"
                                oninput="filterMaterialsDropdown()"
                                onfocus="showMaterialsDropdown()"
                            >
                            <div id="materials-dropdown" class="materials-dropdown" style="display: none;"></div>
                        </div>
                        <button type="button" class="btn btn-link" onclick="toggleAddNewMaterial()" style="margin-top: 5px; padding: 0; font-size: 12px;">
                            ➕ Добавить новый материал "на лету"
                        </button>
                        <div id="new-material-form" style="display: none; margin-top: 10px; padding: 10px; background: #f5f5f5; border-radius: 4px;">
                            <input type="text" id="new-material-name" placeholder="Название нового материала" style="width: 100%; margin-bottom: 5px;">
                            <div class="form-row">
                                <select id="new-material-unit" style="flex: 1; margin-right: 5px;">
                                    <option value="">Единица измерения</option>
                                    ${units.map(u => `<option value="${u.id}">${u.name} (${u.short_name})</option>`).join('')}
                                </select>
                                <button type="button" class="btn btn-primary" onclick="addNewMaterialToList()" style="padding: 5px 10px;">Добавить</button>
                            </div>
                        </div>
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>📏 Единица измерения <span class="required">*</span></label>
                            <select id="material-unit" required>
                                <option value="">Выберите единицу</option>
                                ${units.map(u => 
                                    `<option value="${u.id}" ${existingMaterial && existingMaterial.unit_id === u.id ? 'selected' : ''}>
                                        ${u.name} (${u.short_name})
                                    </option>`
                                ).join('')}
                            </select>
                        </div>
                        <div class="form-group">
                            <label>🔢 Количество (смета) <span class="required">*</span></label>
                            <input 
                                type="number" 
                                id="material-quantity" 
                                step="0.01" 
                                required 
                                placeholder="0.00"
                                value="${existingMaterial ? (existingMaterial.planned_quantity || '') : ''}"
                            >
                        </div>
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>💰 Цена за единицу</label>
                            <input 
                                type="number" 
                                id="material-price" 
                                step="0.01" 
                                placeholder="0.00"
                                value="${existingMaterial ? (existingMaterial.planned_price || '') : ''}"
                                oninput="calculateMaterialCost()"
                            >
                        </div>
                        <div class="form-group">
                            <label>💵 Стоимость (автоматически)</label>
                            <input 
                                type="number" 
                                id="material-cost" 
                                step="0.01" 
                                readonly
                                placeholder="0.00"
                                value="${existingMaterial ? (existingMaterial.planned_cost || '') : ''}"
                            >
                        </div>
                    </div>
                    <div class="form-actions">
                        <button type="button" class="btn btn-secondary" onclick="closeAddMaterialModal()">Отмена</button>
                        <button type="submit" class="btn btn-primary">💾 Сохранить</button>
                    </div>
                </form>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
    
    // Если редактируем, устанавливаем material_id и заполняем данные
    if (existingMaterial) {
        const form = document.getElementById('add-material-form');
        
        // Устанавливаем material_id из _list_mat, если есть
        if (existingMaterial.material_id) {
            form.setAttribute('data-material-id', existingMaterial.material_id);
        } else if (materialFromList) {
            form.setAttribute('data-material-id', materialFromList.id);
        }
        
        // Если есть материал из _list_mat, используем его данные для автозаполнения
        if (materialFromList) {
            // Автоматически выбираем единицу измерения из справочника
            const unitSelect = document.getElementById('material-unit');
            if (materialFromList.primary_unit && unitSelect) {
                unitSelect.value = materialFromList.primary_unit;
            }
            
            // Автоматически выбираем категорию из справочника
            const categorySelect = document.getElementById('material-category');
            if (materialFromList.cat_expense_id && categorySelect) {
                categorySelect.value = materialFromList.cat_expense_id;
            }
        }
    }
    
    document.getElementById('material-name-search').focus();
}

// Фильтрация выпадающего списка материалов
function filterMaterialsDropdown() {
    clearTimeout(materialsDropdownTimeout);
    const searchInput = document.getElementById('material-name-search');
    if (!searchInput) return;
    
    const search = searchInput.value.trim(); // Убираем toLowerCase(), чтобы сохранить кириллицу
    const dropdown = document.getElementById('materials-dropdown');
    
    if (!dropdown) return;
    
    if (!search) {
        dropdown.innerHTML = '';
        dropdown.style.display = 'none';
        return;
    }
    
    materialsDropdownTimeout = setTimeout(async () => {
        try {
            const filtered = await loadMaterialsList(search);
            if (filtered.length === 0) {
                dropdown.innerHTML = '<div class="dropdown-item">Материал не найден</div>';
            } else {
                dropdown.innerHTML = filtered.slice(0, 10).map(mat => `
                    <div class="dropdown-item" onclick="selectMaterial(${mat.id}, '${mat.mat.replace(/'/g, "\\'").replace(/"/g, '&quot;')}', ${mat.primary_unit || 'null'}, ${mat.cat_expense_id || 'null'})">
                        ${mat.category_icon || ''} ${mat.mat} 
                        <span style="color: #999; font-size: 12px;">(${mat.primary_unit_name || ''})</span>
                    </div>
                `).join('');
            }
            dropdown.style.display = 'block';
        } catch (error) {
            console.error('Ошибка поиска материалов:', error);
            dropdown.innerHTML = '<div class="dropdown-item" style="color: red;">Ошибка поиска</div>';
            dropdown.style.display = 'block';
        }
    }, 300);
}

// Показать выпадающий список
async function showMaterialsDropdown() {
    const searchInput = document.getElementById('material-name-search');
    if (!searchInput) return;
    
    const search = searchInput.value.trim();
    const dropdown = document.getElementById('materials-dropdown');
    if (!dropdown) return;
    
    if (search) {
        filterMaterialsDropdown();
    } else {
        // Показываем первые 10 материалов
        if (materialsList.length === 0) {
            await loadMaterialsList();
        }
        dropdown.innerHTML = materialsList.slice(0, 10).map(mat => `
            <div class="dropdown-item" onclick="selectMaterial(${mat.id}, '${mat.mat.replace(/'/g, "\\'").replace(/"/g, '&quot;')}', ${mat.primary_unit || 'null'}, ${mat.cat_expense_id || 'null'})">
                ${mat.category_icon || ''} ${mat.mat} 
                <span style="color: #999; font-size: 12px;">(${mat.primary_unit_name || ''})</span>
            </div>
        `).join('');
        dropdown.style.display = 'block';
    }
}

// Выбор материала из списка
function selectMaterial(materialId, materialName, unitId, categoryId) {
    document.getElementById('material-name-search').value = materialName;
    document.getElementById('add-material-form').setAttribute('data-material-id', materialId);
    
    if (unitId) {
        document.getElementById('material-unit').value = unitId;
    }
    
    if (categoryId) {
        document.getElementById('material-category').value = categoryId;
    }
    
    document.getElementById('materials-dropdown').style.display = 'none';
}

// Переключение формы добавления нового материала
function toggleAddNewMaterial() {
    const form = document.getElementById('new-material-form');
    form.style.display = form.style.display === 'none' ? 'block' : 'none';
}

// Добавление нового материала в _list_mat "на лету"
async function addNewMaterialToList() {
    const name = document.getElementById('new-material-name').value.trim();
    const unitId = document.getElementById('new-material-unit').value;
    const categoryId = document.getElementById('material-category').value;
    
    if (!name || !unitId || !categoryId) {
        alert('Заполните все поля: название, единица измерения и категория');
        return;
    }
    
    try {
        const newMaterial = await listMatAPI.create({
            mat: name,
            cat_expense_id: parseInt(categoryId),
            primary_unit: parseInt(unitId)
        });
        
        // Обновляем список материалов
        await loadMaterialsList();
        
        // Выбираем новый материал
        selectMaterial(newMaterial.id, newMaterial.mat, newMaterial.primary_unit, newMaterial.cat_expense_id);
        
        // Скрываем форму добавления
        document.getElementById('new-material-form').style.display = 'none';
        document.getElementById('new-material-name').value = '';
        document.getElementById('new-material-unit').value = '';
        
        alert('✅ Материал добавлен в справочник!');
    } catch (error) {
        console.error('Ошибка добавления материала:', error);
        alert('Ошибка добавления материала: ' + error.message);
    }
}

// Расчёт стоимости материала
function calculateMaterialCost() {
    const quantity = parseFloat(document.getElementById('material-quantity').value) || 0;
    const price = parseFloat(document.getElementById('material-price').value) || 0;
    const cost = quantity * price;
    document.getElementById('material-cost').value = cost.toFixed(2);
}

// Закрытие модального окна
function closeAddMaterialModal() {
    const modal = document.getElementById('add-material-modal');
    if (modal) {
        modal.style.display = 'none';
        modal.remove();
    }
}

// Сохранение материала
async function saveMaterial(materialId = null) {
    try {
        const form = document.getElementById('add-material-form');
        const materialIdFromList = form.getAttribute('data-material-id');
        const materialName = document.getElementById('material-name-search').value.trim();
        const categoryId = parseInt(document.getElementById('material-category').value);
        const unitId = parseInt(document.getElementById('material-unit').value);
        const quantity = parseFloat(document.getElementById('material-quantity').value);
        const price = parseFloat(document.getElementById('material-price').value) || 0;
        const cost = quantity * price;
        
        if (!materialName || !categoryId || !unitId || !quantity) {
            alert('Заполните все обязательные поля');
            return;
        }
        
        const category = expenseCategories.find(c => c.id === categoryId);
        
        const data = {
            project_id: currentProjectId,
            category: category ? category.name : '',
            material_name: materialName,
            unit_id: unitId,
            planned_quantity: quantity,
            planned_price: price,
            planned_cost: cost,
            resource_category_id: categoryId,
            material_id: materialIdFromList ? parseInt(materialIdFromList) : null
        };
        
        if (materialId) {
            // Обновление
            await projectMaterialsAPI.update(materialId, data);
        } else {
            // Создание
            await projectMaterialsAPI.create(data);
        }
        
        closeAddMaterialModal();
        await loadMaterials(); // Обновляем список материалов в СНАБ
    } catch (error) {
        console.error('Ошибка сохранения материала:', error);
        alert('Ошибка сохранения материала: ' + error.message);
    }
}

// Закрытие выпадающего списка при клике вне его
document.addEventListener('click', (e) => {
    if (!e.target.closest('#material-name-search') && !e.target.closest('#materials-dropdown')) {
        const dropdown = document.getElementById('materials-dropdown');
        if (dropdown) {
            dropdown.style.display = 'none';
        }
    }
});

// Функция для расчёта часов из времени
function calculateHours(timeStart, timeEnd, breakDuration) {
    if (!timeStart || !timeEnd) return null;
    
    const start = new Date(`2000-01-01T${timeStart}`);
    const end = new Date(`2000-01-01T${timeEnd}`);
    let diff = (end - start) / (1000 * 60 * 60); // разница в часах
    
    if (breakDuration) {
        // breakDuration в формате "HH:MM" или "HH:MM:SS"
        const breakMatch = breakDuration.match(/(\d+):(\d+)/);
        if (breakMatch) {
            const breakHours = parseInt(breakMatch[1]) + parseInt(breakMatch[2]) / 60;
            diff -= breakHours;
        }
    }
    
    return Math.max(0, Math.round(diff * 100) / 100); // округляем до 2 знаков
}

// Открытие модального окна для добавления записи в журнал
function openAddJournalModal() {
    openJournalModal(null);
}

// Открытие модального окна для редактирования записи в журнале
async function openEditJournalModal(id) {
    try {
        const journalEntry = await projectJournalAPI.getById(id);
        if (!journalEntry) {
            alert('Запись не найдена');
            return;
        }
        openJournalModal(journalEntry);
    } catch (error) {
        console.error('Ошибка загрузки записи:', error);
        alert('Ошибка загрузки записи');
    }
}

// Создание/открытие модального окна для журнала
function openJournalModal(entry = null) {
    const isEdit = entry !== null;
    const modalId = 'journal-modal';
    
    // Удаляем существующее модальное окно, если есть
    const existingModal = document.getElementById(modalId);
    if (existingModal) {
        existingModal.remove();
    }
    
    // Получаем список работ для выпадающего списка
    const worksOptions = works.map(w => 
        `<option value="${w.id}" ${entry && entry.work_id === w.id ? 'selected' : ''}>${w.work_name}</option>`
    ).join('');
    
        // Получаем выбранных сотрудников
        const selectedEmployeeIds = entry && entry.employees ? entry.employees.map(e => e.id) : [];
        
        // Извлекаем подрядчика из notes, если есть
        const contractorValue = entry && entry.notes && entry.notes.includes('Подрядчик') 
            ? entry.notes.replace('Подрядчик', '').trim() 
            : '';
        
        // Определяем цвета статусов
        const statusColors = {
            'Работает': '#5cb85c',
            'Уволен': '#d9534f',
            'Кандидат': '#f0ad4e',
            'Запас': '#5bc0de',
            'Консультант': '#9b59b6',
            'Подрядчик': '#e67e22',
            'Временный': '#95a5a6',
            'Не указан': '#95a5a6'
        };
        
        // Получаем уникальные статусы из списка сотрудников
        const uniqueStatuses = [...new Set(employees.map(emp => emp.status || 'Не указан'))].sort();
        
        // Создаём фильтр статусов
        const statusFilterHTML = `
            <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 12px; flex-wrap: wrap;">
                <button type="button" class="status-filter-btn" data-status="all" style="padding: 6px 12px; border: 2px solid #ddd; background: white; border-radius: 6px; cursor: pointer; font-size: 13px; font-weight: 500; transition: all 0.2s;">
                    Все
                </button>
                ${uniqueStatuses.map(status => {
                    const color = statusColors[status] || '#95a5a6';
                    const isDefault = status === 'Работает' || status === 'Подрядчик';
                    const size = isDefault ? '24px' : '12px';
                    return `
                        <div style="width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; margin: 0 2px;">
                            <button type="button" 
                                    class="status-filter-btn ${isDefault ? 'active' : ''}" 
                                    data-status="${status}"
                                    title="${status}"
                                    style="width: ${size}; height: ${size}; border-radius: 50%; border: 2px solid ${color}; background: ${color}; cursor: pointer; transition: all 0.2s; flex-shrink: 0;">
                            </button>
                        </div>
                    `;
                }).join('')}
            </div>
        `;
        
        // Функция для фильтрации сотрудников
        function filterEmployeesByStatus(selectedStatuses) {
            if (selectedStatuses.includes('all')) {
                return employees;
            }
            return employees.filter(emp => selectedStatuses.includes(emp.status || 'Не указан'));
        }
        
        // Начальные выбранные статусы (по умолчанию)
        let selectedStatuses = ['Работает', 'Подрядчик'];
        
        // Функция для рендеринга списка сотрудников
        function renderEmployeesList(filteredEmployees) {
            if (filteredEmployees.length === 0) {
                return '<div style="padding: 20px; text-align: center; color: #999;">Нет сотрудников с выбранными статусами</div>';
            }
            return filteredEmployees.map((emp, index) => {
                const fullName = `${emp.last_name || ''} ${emp.first_name || ''} ${emp.middle_name || ''}`.trim();
                const isChecked = selectedEmployeeIds.includes(emp.id);
                const isLast = index === filteredEmployees.length - 1;
                return `
                <label style="display: flex; align-items: center; gap: 10px; padding: 10px 4px; ${!isLast ? 'border-bottom: 1px solid #e8e8e8;' : ''} cursor: pointer; transition: background 0.2s;">
                    <input type="checkbox" name="employees" value="${emp.id}" ${isChecked ? 'checked' : ''} style="margin: 0; cursor: pointer; width: 18px; height: 18px; flex-shrink: 0;">
                    <span style="flex: 1; user-select: none;">${fullName}</span>
                </label>
            `;
            }).join('');
        }
        
        // Изначально отфильтрованный список
        let filteredEmployees = filterEmployeesByStatus(selectedStatuses);
        let employeesCheckboxes = renderEmployeesList(filteredEmployees);
    
    // Форматируем дату для input[type="date"]
    let dateValue = entry ? entry.date : new Date().toISOString().split('T')[0];
    // Если дата в формате ISO с временем, извлекаем только дату
    if (dateValue && dateValue.includes('T')) {
        dateValue = dateValue.split('T')[0];
    }
    
    const modalHTML = `
        <div id="${modalId}" class="modal-overlay" onclick="if(event.target.id === '${modalId}') closeJournalModal()">
            <div class="modal-content" onclick="event.stopPropagation()">
                <div class="modal-header">
                    <h2>${isEdit ? 'Редактировать запись' : 'Добавить запись в журнал'}</h2>
                    <button class="modal-close" onclick="closeJournalModal()">&times;</button>
                </div>
                <div class="modal-body">
                    <form id="journal-form">
                        <div class="form-row">
                            <div class="form-group">
                                <label>Дата *</label>
                                <input type="date" name="date" value="${dateValue}" required>
                            </div>
                            <div class="form-group">
                                <label>Время начала</label>
                                <input type="time" name="time_start" value="${entry ? (entry.time_start || '') : ''}">
                            </div>
                            <div class="form-group">
                                <label>Время окончания</label>
                                <input type="time" name="time_end" value="${entry ? (entry.time_end || '') : ''}">
                            </div>
                            <div class="form-group">
                                <label>Перерыв (чч:мм)</label>
                                <input type="text" name="break_duration" placeholder="1:00" value="${(() => {
                                    if (!entry || !entry.break_duration) return '';
                                    const breakDuration = String(entry.break_duration);
                                    const match = breakDuration.match(/(\d+):(\d+)/);
                                    return match ? match[0] : breakDuration;
                                })()}">
                            </div>
                            <div class="form-group">
                                <label>Часов (автоматически)</label>
                                <input type="number" step="0.01" name="hours" id="journal-hours" value="${entry ? (entry.hours || '') : ''}" readonly>
                            </div>
                        </div>
                        
                        <div class="form-group">
                            <label>Сотрудники</label>
                            ${statusFilterHTML}
                            <div id="employees-list-container" style="max-height: 200px; overflow-y: auto; border: 2px solid #e0e0e0; padding: 4px 8px; border-radius: 8px; background: white;">
                                ${employeesCheckboxes}
                            </div>
                        </div>
                        
                        <div class="form-group">
                            <label>Работа *</label>
                            <div style="display: flex; align-items: center; gap: 10px;">
                                <select name="work_id" id="journal-work-select" required style="flex: 1;">
                                    <option value="">Выберите работу</option>
                                    ${worksOptions}
                                </select>
                                <div class="journal-work-filters" style="display: flex; gap: 6px; align-items: center; flex-shrink: 0;">
                                    <span class="journal-filter-link" data-filter="all" title="Все работы" style="cursor: pointer; padding: 4px 8px; border-radius: 4px; transition: all 0.2s; user-select: none; font-size: 18px; line-height: 1; border: 2px solid transparent;">📋</span>
                                    <span class="journal-filter-link" data-filter="done" title="Готово" style="cursor: pointer; padding: 4px 8px; border-radius: 4px; transition: all 0.2s; user-select: none; font-size: 18px; line-height: 1; border: 2px solid transparent;">✔</span>
                                    <span class="journal-filter-link" data-filter="remaining" title="Остались" style="cursor: pointer; padding: 4px 8px; border-radius: 4px; transition: all 0.2s; user-select: none; font-size: 18px; line-height: 1; border: 2px solid transparent;">⏰</span>
                                    <span class="journal-filter-link" data-filter="in-progress" title="В процессе" style="cursor: pointer; padding: 4px 8px; border-radius: 4px; transition: all 0.2s; user-select: none; font-size: 18px; line-height: 1; border: 2px solid transparent;">⏳</span>
                                </div>
                            </div>
                            <div id="work-quantity-hint" style="margin-top: 8px; padding: 8px; background-color: #f0f0f0; border-radius: 4px; font-size: 13px; display: none;">
                                <div><strong>Информация о работе:</strong></div>
                                <div id="work-quantity-info"></div>
                            </div>
                        </div>
                        
                        <div class="form-group">
                            <label>Выполнено (количество)</label>
                            <input type="number" step="0.01" name="quantity_completed" value="${entry ? (entry.quantity_completed || '') : ''}">
                        </div>
                        
                        <div class="modal-footer">
                            <button type="button" class="btn btn-secondary" onclick="closeJournalModal()">Отмена</button>
                            <button type="submit" class="btn btn-primary">${isEdit ? 'Сохранить' : 'Добавить'}</button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    `;
    
    document.getElementById('modals-container').innerHTML = modalHTML;
    
    // Добавляем обработчики для автоматического расчёта часов
    const timeStartInput = document.querySelector(`#${modalId} input[name="time_start"]`);
    const timeEndInput = document.querySelector(`#${modalId} input[name="time_end"]`);
    const breakDurationInput = document.querySelector(`#${modalId} input[name="break_duration"]`);
    const hoursInput = document.getElementById('journal-hours');
    
    function updateHours() {
        const timeStart = timeStartInput.value;
        const timeEnd = timeEndInput.value;
        const breakDuration = breakDurationInput.value;
        
        if (timeStart && timeEnd) {
            const hours = calculateHours(timeStart, timeEnd, breakDuration);
            hoursInput.value = hours !== null ? hours.toFixed(2) : '';
        } else {
            hoursInput.value = '';
        }
    }
    
    timeStartInput.addEventListener('change', updateHours);
    timeEndInput.addEventListener('change', updateHours);
    breakDurationInput.addEventListener('input', updateHours);
    
    // Обработчик изменения выбора работы - показываем подсказку с количеством
    const workSelect = document.getElementById('journal-work-select');
    const workHint = document.getElementById('work-quantity-hint');
    const workInfo = document.getElementById('work-quantity-info');
    
    workSelect.addEventListener('change', () => {
        const selectedWorkId = parseInt(workSelect.value);
        if (selectedWorkId && works.length > 0) {
            const selectedWork = works.find(w => w.id === selectedWorkId);
            if (selectedWork) {
                const plannedQty = parseFloat(selectedWork.quantity) || 0;
                const completedQty = parseFloat(selectedWork.completed_quantity) || 0;
                const remainingQty = plannedQty - completedQty;
                const unitName = selectedWork.unit_short_name || selectedWork.unit_name || '';
                
                let infoHTML = '';
                if (plannedQty > 0) {
                    infoHTML = `
                        <div style="margin-top: 4px;">Всего в смете: <strong>${formatNumber(plannedQty)} ${unitName}</strong></div>
                        <div style="margin-top: 4px;">Уже выполнено: <strong>${formatNumber(completedQty)} ${unitName}</strong></div>
                        <div style="margin-top: 4px; color: ${remainingQty > 0 ? '#d9534f' : '#5cb85c'};">
                            Осталось: <strong>${formatNumber(remainingQty)} ${unitName}</strong>
                        </div>
                    `;
                } else {
                    infoHTML = '<div style="color: #d9534f;">⚠️ Количество в смете не указано</div>';
                }
                
                workInfo.innerHTML = infoHTML;
                workHint.style.display = 'block';
            } else {
                workHint.style.display = 'none';
            }
        } else {
            workHint.style.display = 'none';
        }
    });
    
    // Если редактируем запись, сразу показываем подсказку
    if (entry && entry.work_id) {
        workSelect.dispatchEvent(new Event('change'));
    }
    
    // Фильтрация работ в модальном окне
    let activeWorkFilters = ['remaining', 'in-progress']; // По умолчанию активны "остались" и "в процессе"
    
    // Функция для фильтрации работ по выбранным фильтрам
    function filterWorksForJournal(worksList, filters) {
        if (!worksList || worksList.length === 0) {
            return [];
        }
        
        // Если выбран фильтр "all", показываем все работы
        if (filters.includes('all')) {
            return worksList;
        }
        
        // Если не выбрано ни одного фильтра, показываем все
        if (filters.length === 0) {
            return worksList;
        }
        
        return worksList.filter(work => {
            const progress = parseFloat(work.progress_percent) || 0;
            const completed = parseFloat(work.completed_quantity) || 0;
            const quantity = parseFloat(work.quantity) || 0;
            const remaining = quantity - completed;
            
            // Проверяем, соответствует ли работа хотя бы одному из активных фильтров
            return filters.some(filter => {
                switch (filter) {
                    case 'done':
                        // Готов: прогресс >= 100
                        return progress >= 100;
                    case 'remaining':
                        // Остались: есть что делать (completed < quantity)
                        return remaining > 0;
                    case 'in-progress':
                        // В процессе: прогресс > 0 и < 100
                        return progress > 0 && progress < 100;
                    default:
                        return false;
                }
            });
        });
    }
    
    // Функция для обновления списка работ в select
    function updateWorkSelect() {
        const filteredWorks = filterWorksForJournal(works, activeWorkFilters);
        const currentValue = workSelect.value;
        
        // Сохраняем выбранную работу, если она есть в отфильтрованном списке
        const currentWork = works.find(w => w.id === parseInt(currentValue));
        const shouldKeepSelection = currentWork && filteredWorks.some(w => w.id === currentWork.id);
        
        // Очищаем select
        workSelect.innerHTML = '<option value="">Выберите работу</option>';
        
        // Добавляем отфильтрованные работы
        filteredWorks.forEach(work => {
            const option = document.createElement('option');
            option.value = work.id;
            option.textContent = work.work_name;
            if (shouldKeepSelection && work.id === currentWork.id) {
                option.selected = true;
            }
            workSelect.appendChild(option);
        });
        
        // Если выбранная работа не попала в фильтр, сбрасываем выбор
        if (!shouldKeepSelection && currentValue) {
            workSelect.value = '';
            workHint.style.display = 'none';
        }
    }
    
    // Обработчики кликов на фильтры
    document.querySelectorAll('.journal-filter-link').forEach(link => {
        link.addEventListener('click', function() {
            const filter = this.getAttribute('data-filter');
            
            // Если это фильтр "all", он работает как переключатель (включает/выключает все)
            if (filter === 'all') {
                if (activeWorkFilters.includes('all')) {
                    // Если "all" активен, выключаем его и включаем остальные фильтры по умолчанию
                    activeWorkFilters = ['remaining', 'in-progress'];
                } else {
                    // Включаем "all" и выключаем остальные
                    activeWorkFilters = ['all'];
                }
            } else {
                // Для остальных фильтров - переключаем состояние
                if (activeWorkFilters.includes(filter)) {
                    activeWorkFilters = activeWorkFilters.filter(f => f !== filter);
                    // Если все фильтры выключены, включаем "all"
                    if (activeWorkFilters.length === 0) {
                        activeWorkFilters = ['all'];
                    }
                } else {
                    // Убираем "all", если он был активен
                    activeWorkFilters = activeWorkFilters.filter(f => f !== 'all');
                    activeWorkFilters.push(filter);
                }
            }
            
            // Обновляем визуальное состояние фильтров
            document.querySelectorAll('.journal-filter-link').forEach(l => {
                const f = l.getAttribute('data-filter');
                if (f === 'all') {
                    if (activeWorkFilters.includes('all')) {
                        l.classList.add('active');
                        l.style.border = '2px solid #3498db';
                        l.style.backgroundColor = '#3498db';
                        l.style.color = 'white';
                    } else {
                        l.classList.remove('active');
                        l.style.border = '2px solid transparent';
                        l.style.backgroundColor = 'transparent';
                        l.style.color = 'inherit';
                    }
                } else {
                    if (activeWorkFilters.includes(f)) {
                        l.classList.add('active');
                        l.style.border = '2px solid #27ae60';
                        l.style.backgroundColor = '#27ae60';
                        l.style.color = 'white';
                    } else {
                        l.classList.remove('active');
                        l.style.border = '2px solid transparent';
                        l.style.backgroundColor = 'transparent';
                        l.style.color = 'inherit';
                    }
                }
            });
            
            // Обновляем список работ
            updateWorkSelect();
        });
    });
    
    // Инициализируем фильтры при открытии модального окна
    document.querySelectorAll('.journal-filter-link').forEach(link => {
        const filter = link.getAttribute('data-filter');
        if (activeWorkFilters.includes(filter)) {
            link.classList.add('active');
            if (filter === 'all') {
                link.style.border = '2px solid #3498db';
                link.style.backgroundColor = '#3498db';
                link.style.color = 'white';
            } else {
                link.style.border = '2px solid #27ae60';
                link.style.backgroundColor = '#27ae60';
                link.style.color = 'white';
            }
        }
    });
    
    // Применяем фильтр при открытии модального окна
    updateWorkSelect();
    
    // Обработчики для фильтра статусов сотрудников
    const statusFilterBtns = document.querySelectorAll(`#${modalId} .status-filter-btn`);
    const employeesListContainer = document.getElementById('employees-list-container');
    
    // Сохраняем функции и переменные для использования в обработчиках
    const currentSelectedStatuses = { value: [...selectedStatuses] };
    
    statusFilterBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            const status = this.getAttribute('data-status');
            const statusColorsMap = {
                'Работает': '#5cb85c',
                'Уволен': '#d9534f',
                'Кандидат': '#f0ad4e',
                'Запас': '#5bc0de',
                'Консультант': '#9b59b6',
                'Подрядчик': '#e67e22',
                'Временный': '#95a5a6',
                'Не указан': '#95a5a6'
            };
            
            function filterEmployeesByStatus(selectedStatuses) {
                if (selectedStatuses.includes('all')) {
                    return employees;
                }
                return employees.filter(emp => selectedStatuses.includes(emp.status || 'Не указан'));
            }
            
            function renderEmployeesList(filteredEmployees) {
                if (filteredEmployees.length === 0) {
                    return '<div style="padding: 20px; text-align: center; color: #999;">Нет сотрудников с выбранными статусами</div>';
                }
                return filteredEmployees.map((emp, index) => {
                    const fullName = `${emp.last_name || ''} ${emp.first_name || ''} ${emp.middle_name || ''}`.trim();
                    const isChecked = selectedEmployeeIds.includes(emp.id);
                    const isLast = index === filteredEmployees.length - 1;
                    return `
                    <label style="display: flex; align-items: center; gap: 10px; padding: 10px 4px; ${!isLast ? 'border-bottom: 1px solid #e8e8e8;' : ''} cursor: pointer; transition: background 0.2s;">
                        <input type="checkbox" name="employees" value="${emp.id}" ${isChecked ? 'checked' : ''} style="margin: 0; cursor: pointer; width: 18px; height: 18px; flex-shrink: 0;">
                        <span style="flex: 1; user-select: none;">${fullName}</span>
                    </label>
                `;
                }).join('');
            }
            
            if (status === 'all') {
                // Если нажата кнопка "Все", сбрасываем все фильтры
                currentSelectedStatuses.value = ['all'];
                statusFilterBtns.forEach(b => {
                    if (b.getAttribute('data-status') === 'all') {
                        b.classList.add('active');
                        b.style.borderColor = '#3498db';
                        b.style.background = '#3498db';
                        b.style.color = 'white';
                    } else {
                        b.classList.remove('active');
                        const statusName = b.getAttribute('data-status');
                        const color = statusColorsMap[statusName] || '#95a5a6';
                        b.style.width = '12px';
                        b.style.height = '12px';
                        b.style.borderColor = color;
                        b.style.background = color;
                    }
                });
            } else {
                // Убираем "all" из выбранных, если он был
                if (currentSelectedStatuses.value.includes('all')) {
                    currentSelectedStatuses.value = [];
                    const allBtn = document.querySelector(`#${modalId} .status-filter-btn[data-status="all"]`);
                    if (allBtn) {
                        allBtn.classList.remove('active');
                        allBtn.style.borderColor = '#ddd';
                        allBtn.style.background = 'white';
                        allBtn.style.color = 'inherit';
                    }
                }
                
                // Переключаем статус
                if (currentSelectedStatuses.value.includes(status)) {
                    currentSelectedStatuses.value = currentSelectedStatuses.value.filter(s => s !== status);
                    this.classList.remove('active');
                    const color = statusColorsMap[status] || '#95a5a6';
                    this.style.width = '12px';
                    this.style.height = '12px';
                    this.style.borderColor = color;
                    this.style.background = color;
                } else {
                    currentSelectedStatuses.value.push(status);
                    this.classList.add('active');
                    const color = statusColorsMap[status] || '#95a5a6';
                    this.style.width = '24px';
                    this.style.height = '24px';
                    this.style.borderColor = color;
                    this.style.background = color;
                }
            }
            
            // Если ничего не выбрано, выбираем "Все"
            if (currentSelectedStatuses.value.length === 0) {
                currentSelectedStatuses.value = ['all'];
                const allBtn = document.querySelector(`#${modalId} .status-filter-btn[data-status="all"]`);
                if (allBtn) {
                    allBtn.classList.add('active');
                    allBtn.style.borderColor = '#3498db';
                    allBtn.style.background = '#3498db';
                    allBtn.style.color = 'white';
                }
            }
            
            // Обновляем список сотрудников
            const filtered = filterEmployeesByStatus(currentSelectedStatuses.value);
            employeesListContainer.innerHTML = renderEmployeesList(filtered);
        });
    });
    
    // Обработчик отправки формы
    document.getElementById('journal-form').addEventListener('submit', async (e) => {
        e.preventDefault();
        await saveJournalEntry(entry);
    });
}

// Закрытие модального окна журнала
function closeJournalModal() {
    const modal = document.getElementById('journal-modal');
    if (modal) {
        modal.remove();
    }
}

// Сохранение записи в журнале
async function saveJournalEntry(entry = null) {
    try {
        const form = document.getElementById('journal-form');
        const formData = new FormData(form);
        
        // Получаем выбранных сотрудников
        const selectedEmployees = Array.from(form.querySelectorAll('input[name="employees"]:checked'))
            .map(cb => parseInt(cb.value));
        
        // Проверяем: должен быть выбран хотя бы один сотрудник
        if (selectedEmployees.length === 0) {
            alert('Выберите хотя бы одного сотрудника');
            return;
        }
        
        const notes = null;
        
        const data = {
            project_id: currentProjectId,
            date: formData.get('date'),
            time_start: formData.get('time_start') || null,
            time_end: formData.get('time_end') || null,
            break_duration: formData.get('break_duration') || null,
            hours: formData.get('hours') ? parseFloat(formData.get('hours')) : null,
            work_id: parseInt(formData.get('work_id')),
            quantity_completed: formData.get('quantity_completed') ? parseFloat(formData.get('quantity_completed')) : null,
            notes: notes,
            employee_ids: selectedEmployees
        };
        
        if (entry) {
            // Обновление
            await projectJournalAPI.update(entry.id, data);
        } else {
            // Создание
            await projectJournalAPI.create(data);
        }
        
        closeJournalModal();
        await loadJournal();
        await loadWorks(); // Обновляем работы, чтобы обновился прогресс
        await loadTimesheet(); // Обновляем табель
    } catch (error) {
        console.error('Ошибка сохранения записи:', error);
        alert('Ошибка сохранения записи: ' + error.message);
    }
}

