// ===========================================
// РЕСУРСЫ РАБОТ
// ===========================================

// Загрузка категорий ресурсов
async function loadResourceCategories() {
    try {
        resourceCategories = await workResourcesAPI.getCategories();
    } catch (error) {
        console.error('Ошибка загрузки категорий ресурсов:', error);
    }
}

// Раскрытие/сворачивание аккордеона ресурсов
async function toggleWorkResources(workId) {
    const resourcesRow = document.querySelector(`tr.work-resources-row[data-work-id="${workId}"]`);
    const workRow = document.querySelector(`tr.work-progress-row[data-work-id="${workId}"]`);
    
    if (!resourcesRow || !workRow) {
        console.error('Не найдены строки для работы ID:', workId);
        console.error('resourcesRow:', resourcesRow);
        console.error('workRow:', workRow);
        return;
    }
    
    const isExpanded = expandedWorks.has(workId);
    
    if (isExpanded) {
        // Сворачиваем
        resourcesRow.style.display = 'none';
        resourcesRow.classList.remove('active');
        workRow.classList.remove('work-row-expanded');
        expandedWorks.delete(workId);
        
        // Обновляем стрелку
        const arrow = workRow.querySelector('td:first-child span');
        if (arrow) arrow.textContent = '▼';
    } else {
        // Раскрываем
        resourcesRow.style.display = 'table-row';
        resourcesRow.classList.add('active');
        workRow.classList.add('work-row-expanded');
        expandedWorks.add(workId);
        
        // Обновляем стрелку
        const arrow = workRow.querySelector('td:first-child span');
        if (arrow) arrow.textContent = '▲';
        
        // Загружаем ресурсы, если ещё не загружены
        await loadWorkResources(workId);
    }
}

// Загрузка ресурсов для работы
async function loadWorkResources(workId) {
    try {
        const resources = await workResourcesAPI.getByWork(workId);
        renderWorkResources(workId, resources);
    } catch (error) {
        console.error('Ошибка загрузки ресурсов:', error);
        const listDiv = document.getElementById(`resources-list-${workId}`);
        if (listDiv) {
            listDiv.innerHTML = '<div class="empty-state">Ошибка загрузки ресурсов</div>';
        }
    }
}

// Отображение ресурсов
function renderWorkResources(workId, resources) {
    const listDiv = document.getElementById(`resources-list-${workId}`);
    if (!listDiv) return;
    
    if (resources.length === 0) {
        listDiv.innerHTML = '<div class="empty-state">Нет ресурсов. Нажмите "Добавить ресурс"</div>';
        return;
    }
    
    let html = '';
    resources.forEach(resource => {
        const sharedBadge = resource.is_shared ? '<span class="resource-shared">(общий)</span>' : '';
        html += `
            <div class="work-resource-item">
                <div class="resource-name">${resource.material_name} ${sharedBadge}</div>
                <div class="resource-category">${resource.category_name || ''}</div>
                <div class="resource-quantity">${formatNumber(resource.quantity)}</div>
                <div class="resource-unit">${resource.unit_short_name || resource.unit_name || ''}</div>
                <div class="resource-actions">
                    <button class="action-btn edit-btn" onclick="event.stopPropagation(); openEditResourceModal(${resource.id})" title="Редактировать">✏️</button>
                    <button class="action-btn delete-btn" onclick="event.stopPropagation(); deleteResource(${resource.id}, ${workId})" title="Удалить">✕</button>
                </div>
            </div>
        `;
    });
    
    listDiv.innerHTML = html;
}

// Открытие модального окна для добавления ресурса
async function openAddResourceModal(workId) {
    if (resourceCategories.length === 0) {
        await loadResourceCategories();
    }
    
    // Создаём модальное окно
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.id = 'add-resource-modal';
    modal.style.display = 'block'; // Показываем модальное окно
    modal.innerHTML = `
        <div class="modal-content resource-modal" style="max-width: 550px;">
            <div class="modal-header">
                <h3>➕ Добавить ресурс</h3>
                <button class="modal-close" onclick="closeAddResourceModal()">×</button>
            </div>
            <div class="modal-body">
                <form id="add-resource-form" onsubmit="event.preventDefault(); saveResource(${workId})">
                    <div class="form-group">
                        <label>📦 Категория <span class="required">*</span></label>
                        <select id="resource-category" required>
                            <option value="">Выберите категорию</option>
                            ${resourceCategories.map(cat => `<option value="${cat.id}">${cat.name}</option>`).join('')}
                        </select>
                    </div>
                    <div class="form-group">
                        <label>📝 Наименование <span class="required">*</span></label>
                        <input type="text" id="resource-name" required placeholder="Например: доска 50х200х6000">
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>📏 Единица измерения <span class="required">*</span></label>
                            <select id="resource-unit" required>
                                <option value="">Выберите единицу</option>
                                ${units.map(u => `<option value="${u.id}">${u.name} (${u.short_name})</option>`).join('')}
                            </select>
                        </div>
                        <div class="form-group">
                            <label>🔢 Количество <span class="required">*</span></label>
                            <input type="number" id="resource-quantity" step="0.01" required placeholder="0.00">
                        </div>
                    </div>
                    <div class="form-group checkbox-group">
                        <label class="checkbox-label">
                            <input type="checkbox" id="resource-shared" class="custom-checkbox"> 
                            <span>🔗 Общий ресурс (не суммировать между работами)</span>
                        </label>
                    </div>
                    <div class="form-group">
                        <label>💬 Примечания</label>
                        <textarea id="resource-notes" rows="3" placeholder="Дополнительная информация (необязательно)"></textarea>
                    </div>
                    <div class="form-actions">
                        <button type="button" class="btn btn-secondary" onclick="closeAddResourceModal()">Отмена</button>
                        <button type="submit" class="btn btn-primary">💾 Сохранить</button>
                    </div>
                </form>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
    document.getElementById('resource-name').focus();
}

// Закрытие модального окна
function closeAddResourceModal() {
    const modal = document.getElementById('add-resource-modal');
    if (modal) {
        modal.style.display = 'none';
        modal.remove();
    }
}

// Сохранение ресурса
async function saveResource(workId, resourceId = null) {
    try {
        const data = {
            work_id: workId,
            resource_category_id: parseInt(document.getElementById('resource-category').value),
            material_name: document.getElementById('resource-name').value.trim(),
            unit_id: parseInt(document.getElementById('resource-unit').value),
            quantity: parseFloat(document.getElementById('resource-quantity').value),
            is_shared: document.getElementById('resource-shared').checked,
            notes: document.getElementById('resource-notes').value.trim() || null
        };
        
        if (resourceId) {
            await workResourcesAPI.update(resourceId, data);
            closeEditResourceModal();
        } else {
            await workResourcesAPI.create(data);
            // После создания ресурса нужно синхронизировать с СНАБ
            await syncResourceToMaterials(workId, data);
            closeAddResourceModal();
        }
        
        await loadWorkResources(workId);
        
        // Пересчитываем количество в СНАБ
        await syncAllWorkResourcesToMaterials();
        await loadMaterials(); // Обновляем СНАБ
    } catch (error) {
        console.error('Ошибка сохранения ресурса:', error);
        alert('Ошибка сохранения ресурса: ' + error.message);
    }
}

// Синхронизация ресурса с материалами в СНАБ
async function syncResourceToMaterials(workId, resourceData) {
    try {
        // Проверяем, есть ли уже такой материал в СНАБ
        const materials = await projectMaterialsAPI.getByProject(currentProjectId);
        const existingMaterial = materials.find(m => 
            m.material_name === resourceData.material_name && 
            m.resource_category_id === resourceData.resource_category_id &&
            m.unit_id === resourceData.unit_id
        );
        
        if (existingMaterial) {
            // Если материал уже есть, обновляем количество (если не общий)
            if (!resourceData.is_shared) {
                const newQuantity = parseFloat(existingMaterial.planned_quantity || 0) + parseFloat(resourceData.quantity);
                await projectMaterialsAPI.update(existingMaterial.id, {
                    planned_quantity: newQuantity,
                    planned_cost: newQuantity * (parseFloat(existingMaterial.planned_price) || 0)
                });
            }
            // Если общий - количество не меняем (остаётся 1)
        } else {
            // Если материала нет, создаём новый
            const categoryName = resourceCategories.find(c => c.id === resourceData.resource_category_id)?.name || '';
            await projectMaterialsAPI.create({
                project_id: currentProjectId,
                category: categoryName,
                material_name: resourceData.material_name,
                unit_id: resourceData.unit_id,
                planned_quantity: resourceData.is_shared ? 1 : resourceData.quantity,
                planned_price: 0, // Цену установим позже
                planned_cost: 0,
                resource_category_id: resourceData.resource_category_id
            });
        }
    } catch (error) {
        console.error('Ошибка синхронизации с СНАБ:', error);
    }
}

// Открытие модального окна для редактирования ресурса
async function openEditResourceModal(resourceId) {
    try {
        const resource = await workResourcesAPI.getById(resourceId);
        
        if (!resource) {
            alert('Ресурс не найден');
            return;
        }
        
        if (resourceCategories.length === 0) {
            await loadResourceCategories();
        }
        
        // Создаём модальное окно
        const modal = document.createElement('div');
        modal.className = 'modal';
        modal.id = 'edit-resource-modal';
        modal.style.display = 'block'; // Показываем модальное окно
        modal.innerHTML = `
            <div class="modal-content resource-modal" style="max-width: 550px;">
                <div class="modal-header">
                    <h3>✏️ Редактировать ресурс</h3>
                    <button class="modal-close" onclick="closeEditResourceModal()">×</button>
                </div>
                <div class="modal-body">
                    <form id="edit-resource-form" onsubmit="event.preventDefault(); saveResource(${resource.work_id}, ${resourceId})">
                        <div class="form-group">
                            <label>📦 Категория <span class="required">*</span></label>
                            <select id="resource-category" required>
                                ${resourceCategories.map(cat => 
                                    `<option value="${cat.id}" ${cat.id === resource.resource_category_id ? 'selected' : ''}>${cat.name}</option>`
                                ).join('')}
                            </select>
                        </div>
                        <div class="form-group">
                            <label>📝 Наименование <span class="required">*</span></label>
                            <input type="text" id="resource-name" required value="${resource.material_name}">
                        </div>
                        <div class="form-row">
                            <div class="form-group">
                                <label>📏 Единица измерения <span class="required">*</span></label>
                                <select id="resource-unit" required>
                                    ${units.map(u => 
                                        `<option value="${u.id}" ${u.id === resource.unit_id ? 'selected' : ''}>${u.name} (${u.short_name})</option>`
                                    ).join('')}
                                </select>
                            </div>
                            <div class="form-group">
                                <label>🔢 Количество <span class="required">*</span></label>
                                <input type="number" id="resource-quantity" step="0.01" required value="${resource.quantity}">
                            </div>
                        </div>
                        <div class="form-group checkbox-group">
                            <label class="checkbox-label">
                                <input type="checkbox" id="resource-shared" class="custom-checkbox" ${resource.is_shared ? 'checked' : ''}> 
                                <span>🔗 Общий ресурс (не суммировать между работами)</span>
                            </label>
                        </div>
                        <div class="form-group">
                            <label>💬 Примечания</label>
                            <textarea id="resource-notes" rows="3" placeholder="Дополнительная информация (необязательно)">${resource.notes || ''}</textarea>
                        </div>
                        <div class="form-actions">
                            <button type="button" class="btn btn-secondary" onclick="closeEditResourceModal()">Отмена</button>
                            <button type="submit" class="btn btn-primary">💾 Сохранить</button>
                        </div>
                    </form>
                </div>
            </div>
        `;
        
        document.body.appendChild(modal);
    } catch (error) {
        console.error('Ошибка открытия модального окна:', error);
        alert('Ошибка: ' + error.message);
    }
}

// Закрытие модального окна редактирования
function closeEditResourceModal() {
    const modal = document.getElementById('edit-resource-modal');
    if (modal) {
        modal.style.display = 'none';
        modal.remove();
    }
}

// Удаление ресурса
async function deleteResource(resourceId, workId) {
    if (!confirm('Удалить ресурс?')) return;
    
    try {
        // Получаем информацию о ресурсе перед удалением
        const resource = await workResourcesAPI.getById(resourceId);
        
        await workResourcesAPI.delete(resourceId);
        await loadWorkResources(workId);
        
        // Пересчитываем количество в СНАБ
        await syncAllWorkResourcesToMaterials();
        await loadMaterials(); // Обновляем СНАБ
    } catch (error) {
        console.error('Ошибка удаления ресурса:', error);
        alert('Ошибка удаления ресурса');
    }
}
